for t in range(R + 1):
    adopted_mark = [None] * N
    if t:
        rt = (rates[t - 1] * T).tolist()
        bt = vT_rows[(t - 1) % P]
        for i in range(N):
            e = err[i]
            if e is not None:
                e += rt[i]
                err[i] = e
                bnd[i] += bt[i]
                if e < 0:
                    e = -e
                if e > peak:
                    peak = e
    for node in rb.get(t, ()):
        gen[node] += 1
        if err[node] is None:
            nunknown += 1
        err[node] = None
        bnd[node] = None
    for node in anch_nodes[t % P]:
        if err[node] is None:
            nunknown -= 1
        err[node] = 0
        bnd[node] = 0
    row = due[t] if t < len(due) else ()
    if row:
        best = {}
        for pkt in row:
            delivered += 1
            sid, A, src, dst, gsrc, gdst, snap, e0, b0, t0, d, q = pkt
            if gen[src] != gsrc or gen[dst] != gdst:
                stale_cnt += 1
                continue
            if snap is None:
                unknown_cnt += 1
                continue
            cb = b0 + F.aging(dst, t0 % P, d, q)
            ce = e0 + _signed_aging(rates, dst, t0, d, q, T)
            cur = best.get(dst)
            if cur is None or cb < cur[0] or (cb == cur[0] and sid < cur[1]):
                best[dst] = (cb, sid, ce)
        for dst, (cb, sid, ce) in best.items():
            hb = bnd[dst]
            if hb is None or cb < hb:
                if hb is None:
                    nunknown -= 1
                bnd[dst] = cb
                err[dst] = ce
                adopted_mark[dst] = sid
                adopted_cnt += 1
                if ce < 0:
                    ce = -ce
                if ce > peak:
                    peak = ce
        due[t] = ()
    if nunknown:
        always = False
    if t in qpos:
        for pos in qpos[t]:
            states[pos] = {'bounds_as': list(bnd), 'errors_as': list(err),
                           'adopted': list(adopted_mark),
                           'generations': list(gen)}
    batch = by_tick.get(t)
